 "content": "from collections import Counter

def transform(grid):
    """Reduce each 3x3 patch to its most frequent non-background color."""
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError("grid dimensions must be divisible by 3")
    out = []
    for r in range(0, h, 3):
        row_out = []
        for c in range(0, w, 3):
            patch = [grid[y][x] for y in range(r, r + 3) for x in range(c, c + 3)]
            counts = Counter(v for v in patch if v != bg)
            if not counts:
                row_out.append(bg)
            else:
                row_out.append(counts.most_common(1)[0][0])
        out.append(row_out)
    return out
